snapshot.customCss:
.device {
  --glass: rgba(255,255,255,.62);
  --glass-strong: rgba(255,255,255,.9);
  --glass-border: rgba(0,0,0,.05);
}
html[data-theme="dark"] .device {
  --glass: rgba(28,28,32,.68);
  --glass-strong: rgba(40,40,46,.9);
  --glass-border: rgba(255,255,255,.08);
}
.wg-profile,.wg-hero,.wg-note,.wg-quote {
  background: rgba(255,255,255,.92);
  border: 1px solid rgba(0,0,0,.05);
  box-shadow: 0 0 0 0.5px rgba(255,255,255,.9);
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
  border-radius: 18px;
}
html[data-theme="dark"] .wg-profile,
html[data-theme="dark"] .wg-hero,
html[data-theme="dark"] .wg-note,
html[data-theme="dark"] .wg-quote {
  background: rgba(36,36,36,.92);
  border-color: rgba(255,255,255,.08);
  box-shadow: 0 0 0 0.5px rgba(36,36,36,.9);
}

snapshot.chatListCss:
/* 白茶 · 会话列表 */
.chat-list-sheet{
  background:rgba(255,250,242,.88);
  border-radius:18px;overflow:hidden;
  box-shadow:0 8px 28px rgba(90,70,40,.06);
}
.chat-row-slider{background:transparent !important}
.chat-row{padding:13px 14px}
.chat-row-top strong{font-weight:500;letter-spacing:.02em}
.chat-row-preview{color:#9a8f82;font-size:11px}
.chat-row-unread{
  background:#5c5040;color:#fff8f0;border-radius:999px;
}

snapshot.chatThreadCss:
/* 白茶 · 对话气泡 */
.chat-thread{
  --dress-bubble-me-bg:#4a433a;
  --dress-bubble-me-fg:#fff8f0;
  --dress-bubble-them-bg:rgba(255,250,242,.96);
  --dress-bubble-them-fg:#3a342c;
}
.chat-msg.is-them .chat-bubble,
html[data-theme="dark"] .chat-msg.is-them .chat-bubble{
  background:var(--dress-bubble-them-bg);
  color:var(--dress-bubble-them-fg);
  border-radius:18px 18px 18px 6px;
  border:1px solid rgba(120,100,70,.1);
  box-shadow:0 2px 10px rgba(90,70,40,.05);
}
.chat-msg.is-me .chat-bubble,
html[data-theme="dark"] .chat-msg.is-me .chat-bubble{
  background:var(--dress-bubble-me-bg);
  color:var(--dress-bubble-me-fg);
  border-radius:18px 18px 6px 18px;
}
